using System;
public static class LetterStory
{
 [Serializable] public class Visitor {
  public string name,role,portrait,story,gesture,address; public string[] feelings,letters,reactions; public int best;
  public Visitor(string n,string r,string p,string s,string g,string a,string[] f,string[] l,string[] re,int b=0){name=n;role=r;portrait=p;story=s;gesture=g;address=a;feelings=f;letters=l;reactions=re;best=b;}
 }
 public static string[] Themes={"Hope","Anxiety","Fear","Desperation","Grief","Silence","Home"};
 public static string[] Headlines={
 "Military Officials Report Progress Along the Eastern Front.",
 "Evacuations Ordered Near the Front as Fighting Intensifies.",
 "Field Hospitals Overwhelmed Following Heavy Casualties.",
 "Military Command Confirms Withdrawal From Multiple Positions.",
 "Supply Bridge Destroyed; Medical Units Unaccounted For.",
 "No Contact With the Seventh Medical Station.",
 "Survivors Arrive as a Temporary Ceasefire Takes Hold."};
 public static string[] Articles={
 "The ministry describes the situation as difficult but manageable. Medical units remain at their posts, and supply trains continue east. Families are encouraged to use the civilian letter service.\n\nAt the bottom of the page, in smaller print: the names of three towns no longer taking mail.",
 "Families have been ordered to leave settlements along the river. Several medical stations have relocated overnight. Officials ask relatives to allow extra time for correspondence.\n\nA route can move faster than a letter. Mira folds the paper along its old crease.",
 "Field hospitals report shortages of dressings and medicine. Staff are treating patients in railway sheds. Casualty lists will be published when records can be confirmed.\n\nMira knows what 'when records can be confirmed' sounds like in a ward.",
 "Several positions have been abandoned. Telegraph lines are unreliable; medical convoys have been told to travel without lights.\n\nA new notice at the post office limits each family to one sheet of paper. Outside, a window has been boarded shut.",
 "The bridge carrying the last supply railway was destroyed overnight. The whereabouts of several mobile medical units remain unknown. No list of survivors is available.\n\nMira reads the same paragraph three times. Ada's station lies beyond that bridge.",
 "Attempts to reach the Seventh Medical Station have failed. Its staff are listed as missing, not confirmed dead. Residents are asked not to gather at the telegraph office.\n\nThere is no letter. No name. Only a blank space where news should be.",
 "An unmarked convoy brought wounded civilians and medical staff into town before dawn. A temporary ceasefire has allowed survivors to cross the river on foot. Identification is still underway.\n\nThe rain has softened. Mira opens the post office, as she has every morning."};
 public static string[] Notices={"CIVILIAN POST • OPEN","DELAYS ON EASTERN ROUTES","MEDICAL SUPPLIES REQUESTED","ONE SHEET PER HOUSEHOLD","EASTBOUND MAIL SUSPENDED","PLEASE AWAIT CONFIRMED NEWS","MEDICAL CONVOY AT TOWN HALL"};
 public static string[] NightIntros={
 "At home, Mira sets Ada's photograph beside the typewriter. They were medics together before the bombardment took Mira's voice and left hand. Ada always warmed the tea twice.",
 "The room is quiet enough to hear the joints in her left hand. She oils one finger, then lays a fresh sheet beside Ada's photograph. Perhaps the mail is only late.",
 "She remembers Ada handing her the last clean bandage. Neither had slept. They laughed anyway. Mira begins: 'I am afraid I will never see you again.' She crosses it out.",
 "Ada once learned to understand a raised eyebrow, a tap on the table, the smallest smile. Mira never had to be silent with her. Tonight she leaves the lamp burning.",
 "The eastbound tray has been returned unopened. Mira brings her letters home and ties them with thread. Words can wait here, even when trains cannot.",
 "She checks the door once more. Nothing. Six days, no reply. She will not write goodbye for someone whose story she does not yet know."};
 public static string[] NightLetters={
 "Ada, the kettle still whistles for two. Rest when you can. I am saving the sunny chair for you. Love, Mira.",
 "Ada, I read that your station has moved. Send one line when you can. Even a full stop would be enough.",
 "Do you remember laughing over cold tea in the ward? Please eat. Please sleep. I will be waiting for you.",
 "You learned every word my hands could say. There is one I still owe you: stay. When you can, come home.",
 "The trains have stopped. I am keeping these letters safe. If words cannot cross the river, let love wait here.",
 "No news today. I will not turn silence into goodbye. Tomorrow I will unlock the door. I will keep your chair."};
 static string[] F(params string[] s){return s;}
 public static Visitor[][] Days={
 new[]{new Visitor("Lena","A mother • a scarf knitted twice","mother","My son says he is keeping warm. He has always said that, even with blue fingers. Could we tell him the garden is growing? Something ordinary. Something to come home to.","Mira sets down her pen and nods. She draws a small flower in the margin.","Eli Vale • Eastern signals company",F("Hope","Grief","Anger"),F("Eli, the beans have climbed the fence. There will be enough for two when you come home. Keep a little hope for us.","Eli, every empty chair reminds me how much we have lost. The garden carries on without you.","Eli, I am angry that you left us with nothing but a garden and an empty chair."),F("Yes. The beans. He will know I am still looking after things.","It sounds as though I have already lost him. I haven't.","I am frightened, but I do not want him to carry my anger.")),
 new Visitor("Pip","A child • muddy shoes","child","Dad missed the first snow. I saved some in a jar, but it turned into water. Will he think I forgot?", "Mira smiles and sketches a snowflake. Some things can travel on paper.","Jon Bell • Army transport",F("Reassurance","Regret","Farewell"),F("Dad, I saved you some snow, but it melted. I did not forget you. I will save you the first story when you come home.","Dad, I am sorry I could not keep the snow. I should have taken better care of it.","Dad, the snow has gone, and I suppose it is time to say goodbye."),F("Can we draw the jar too? So he knows I tried?","But I didn't do anything bad, did I?","I only meant goodbye to the snow."))},
 new[]{new Visitor("Tomas","A husband • an unsent apology","husband","My wife is driving ambulances. Before she left, I said her patients mattered more than I did. I was afraid. That doesn't make what I said fair.","Mira turns the paper toward him: 'What do you wish you had said?'","Nell Reed • Ambulance corps",F("Apology","Anger","Longing"),F("Nell, I made my fear your burden. I am sorry. Your work matters, and so do you. You do not owe me an answer.","Nell, you left before we could settle this. I still think you should have stayed.","Nell, the house is too quiet. I miss the sound of your keys in the door."),F("Yes. An apology without asking her to comfort me. Thank you.","No. That is the same argument in nicer handwriting.","I miss her. But I need to own what I said first.")),
 new Visitor("Lena","The same scarf • held tighter","mother","They moved Eli's unit. I don't know where. If this catches up with him, I want him to know there is still a place for him here.","Mira writes: 'We can leave a light in the words.'","Eli Vale • Forwarding service",F("Hope","Farewell","Regret"),F("Eli, wherever this finds you, the gate is unlatched. There is soup on the stove and a place for you at home.","Eli, I have put away your things. I will remember the good days we had.","Eli, I wish I had asked you to stay. I keep going over everything I could have changed."),F("A place. That is what I wanted him to have.","Please don't put his things away yet.","I do have regrets. But he needs a home more than my guilt."))},
 new[]{new Visitor("Lena","A mother • a hospital slip","mother","He is alive. His leg is hurt. He says he is sorry he cannot march. As if I raised him to be useful instead of loved.","Mira touches the medic badge tucked beneath her collar. Then she rolls in the paper.","Eli Vale • River field hospital",F("Reassurance","Anger","Grief"),F("Eli, you never had to earn your place here. Rest. Heal at your own pace. You are my son, not a debt to be repaid.","Eli, you must stop apologizing. You should be angry at what they have done to you.","Eli, I grieve for the life you had before. Nothing will ever be the same again."),F("That is it. My son, before anything else.","He has so much to carry already.","His life is still his. Please leave room for it.")),
 new Visitor("Owen","A friend • ink on his cuffs","husband","My friend says he cannot be brave another day. Everyone keeps telling him to be strong. Can we tell him something else?","Mira writes one word on her notepad: 'Rest.'","Sam Orr • Western relief unit",F("Encouragement","Anger","Regret"),F("Sam, you do not have to be fearless to be loved. Get through this hour. Let someone sit beside you for the next.","Sam, do not let them see you give up. You have to prove that you can endure this.","Sam, I wish we had known what this would cost. We should have made different choices."),F("An hour. Yes. Something small enough to hold.","That is just another way of asking him to be strong.","He needs company today, not yesterday's mistakes."))},
 new[]{new Visitor("Emil","A father • a letter creased with use","father","Write that he was selfish to leave. Write that I never needed him. ...He used to mend the gate for me. I haven't touched it since. I just want him to knock again.","Mira waits through the silence. Then she underlines his last sentence.","Noah Gray • Northern infantry",F("Anger","Regret","Forgiveness"),F("Noah, I am angry that you left. I cannot pretend it did not hurt. I am still learning what to do with that hurt.","Noah, I replay our last argument. I wish I had listened before I let my fear speak for me.","Noah, I spoke from fear. You do not have to win an argument to come home. The gate will open when you knock."),F("It is honest. But I can hear how it might keep him away.","That is part of it. I wish I could say there is a way back.","Leave that last line. I cannot promise we will agree. But the gate can open."),2)},
 new[]{new Visitor("Ruth","A widow • no address to give","widow","They brought his watch. There is nowhere to send this. I know. But I never thanked him for making breakfast when I could not get out of bed. May I write it anyway?","Mira lays out the last good sheet. No address is needed to mean every word.","For Ruth to keep • no destination",F("Grief","Hope","Anger"),F("My love, thank you for the mornings you carried for me. I will miss you in ordinary ways, for all my days.","My love, I will keep breakfast warm until you come home. I am sure that you will find a way.","My love, I am angry that you have left me to face every morning alone."),F("I want to take it home. There is a place beside his watch.","I need to say what is true, even when it hurts.","Some days I am angry. Today, I wanted to thank him."))},
 new[]{new Visitor("Pip","A child • carrying the empty jar","child","Mum says we might leave tomorrow. Dad won't know where to find us. Can a letter leave a trail?","Mira draws the relief station on a scrap of paper, then gives Pip the pencil.","Jon Bell • Relief forwarding desk",F("Reassurance","Farewell","Longing"),F("Dad, we are going to the western relief station. Ask for us there. I have the jar. We are leaving you a trail.","Dad, we have to go now. I do not know if we will find each other again. Goodbye.","Dad, I miss our kitchen and your coat by the door. I wish we could all be home."),F("Now he knows where to look. I can carry the jar.","I don't want to stop looking for him.","I miss those things too. But he needs to know where we are."))},
 new[]{new Visitor("Rowan","A soldier • returned from the camp","soldier","They listed our camp as lost. My sister will think that means all of us. I need her to know I am still here.","He lays a battered identity tag beside the paper. Mira steadies the page.","Elsie Ward • Western relief station",F("Reassurance","Anger","Farewell"),F("Elsie, I am alive. I got out of the camp. I cannot promise when I will reach you, but please keep a place for me. Rowan.","Elsie, they called our camp lost while we were still inside it. I am alive, and I am angry at the silence they sent you.","Elsie, so much of our life is gone. Keep the good days close, and remember me as I was before the war."),F("Alive. Put that first. She may not be able to read any further.","I am angry. But she has been afraid long enough. Let her breathe first.","No. She needs to know I survived. There is still time for us.")),
 new Visitor("Ada","A medic • at last, across the counter","lover","I wrote every night. The bridge went before the letters did. I carried people west, then walked. I had so many things to tell you. Now I cannot find the first word. May I be your last customer?","Mira stands. Her mechanical fingers tremble once, then reach across the counter. She turns over a fresh sheet.","Mira • here, at home",F("Love","Forgiveness","Longing"),F("Mira, I have no brave words left. Only this: I love you. If you will have me, I would like to come home.","Mira, forgive the silence I could not break. I kept trying to find a road back to you.","Mira, every road reminded me of you. I missed your hands, your quiet laugh, the light you leave on."),F("Home, Ada says. It takes her two tries. Mira places her right hand over hers.","Mira shakes her head gently. There is nothing to forgive. She brings Ada's hand to her heart.","Mira opens the drawer. Six letters. Six ways of saying: I missed you too."))}
 };
}
